585: ABSL_ATTRIBUTE_CONST_FUNCTION Duration Seconds(T n) {
586:   if (n >= 0) {  // Note: `NaN >= 0` is false.
587:     if (n >= static_cast<T>((std::numeric_limits<int64_t>::max)())) {
588:       return InfiniteDuration();
