592:     if (std::isnan(n)) return -InfiniteDuration();
593:     if (n <= static_cast<T>((std::numeric_limits<int64_t>::min)())) {
594:       return -InfiniteDuration();
595:     }
596:     return -time_internal::MakePosDoubleDuration(-n);
597:   }
598: }
