1705: // Converts a std::chrono::duration to an absl::Duration.
1706: template <typename Rep, typename Period>
1707: ABSL_ATTRIBUTE_PURE_FUNCTION constexpr Duration FromChrono(
1708:     const std::chrono::duration<Rep, Period>& d) {
1709:   static_assert(IsValidRep64<Rep>(0), "duration::rep is invalid");
1710:   return FromInt64(int64_t{d.count()}, Period{});
1711: }
1712: 
1713: template <typename Ratio>
1714: ABSL_ATTRIBUTE_CONST_FUNCTION int64_t ToInt64(Duration d, Ratio) {
1715:   // Note: This may be used on MSVC, which may have a system_clock period of
1716:   // std::ratio<1, 10 * 1000 * 1000>
1717:   return ToInt64Seconds(d * Ratio::den / Ratio::num);
1718: }
1719: // Fastpath implementations for the 6 common duration units.
1720: ABSL_ATTRIBUTE_CONST_FUNCTION inline int64_t ToInt64(Duration d, std::nano) {
1721:   return ToInt64Nanoseconds(d);
1722: }
1723: ABSL_ATTRIBUTE_CONST_FUNCTION inline int64_t ToInt64(Duration d, std::micro) {
1724:   return ToInt64Microseconds(d);
1725: }
1726: ABSL_ATTRIBUTE_CONST_FUNCTION inline int64_t ToInt64(Duration d, std::milli) {
1727:   return ToInt64Milliseconds(d);
1728: }
1729: ABSL_ATTRIBUTE_CONST_FUNCTION inline int64_t ToInt64(Duration d,
1730:                                                      std::ratio<1>) {
1731:   return ToInt64Seconds(d);
1732: }
1733: ABSL_ATTRIBUTE_CONST_FUNCTION inline int64_t ToInt64(Duration d,
1734:                                                      std::ratio<60>) {
1735:   return ToInt64Minutes(d);
1736: }
1737: ABSL_ATTRIBUTE_CONST_FUNCTION inline int64_t ToInt64(Duration d,
1738:                                                      std::ratio<3600>) {
1739:   return ToInt64Hours(d);
1740: }
1741: 
1742: // Converts an absl::Duration to a chrono duration of type T.
1743: template <typename T>
1744: ABSL_ATTRIBUTE_CONST_FUNCTION T ToChronoDuration(Duration d) {
1745:   using Rep = typename T::rep;
1746:   using Period = typename T::period;
1747:   static_assert(IsValidRep64<Rep>(0), "duration::rep is invalid");
1748:   if (time_internal::IsInfiniteDuration(d))
1749:     return d < ZeroDuration() ? (T::min)() : (T::max)();
1750:   const auto v = ToInt64(d, Period{});
1751:   if (v > (std::numeric_limits<Rep>::max)()) return (T::max)();
1752:   if (v < (std::numeric_limits<Rep>::min)()) return (T::min)();
1753:   return T{v};
1754: }
1755: 
1756: }  // namespace time_internal
