1758: ABSL_ATTRIBUTE_CONST_FUNCTION constexpr bool operator<(Duration lhs,
1759:                                                        Duration rhs) {
1760:   return time_internal::GetRepHi(lhs) != time_internal::GetRepHi(rhs)
1761:              ? time_internal::GetRepHi(lhs) < time_internal::GetRepHi(rhs)
1762:          : time_internal::GetRepHi(lhs) == (std::numeric_limits<int64_t>::min)()
1763:              ? time_internal::GetRepLo(lhs) + 1 <
1764:                    time_internal::GetRepLo(rhs) + 1
1765:              : time_internal::GetRepLo(lhs) < time_internal::GetRepLo(rhs);
1766: }
1767: 
1768: #ifdef ABSL_INTERNAL_TIME_HAS_THREE_WAY_COMPARISON
1769: 
1770: ABSL_ATTRIBUTE_CONST_FUNCTION constexpr std::strong_ordering operator<=>(
1771:     Duration lhs, Duration rhs) {
1772:   const int64_t lhs_hi = time_internal::GetRepHi(lhs);
1773:   const int64_t rhs_hi = time_internal::GetRepHi(rhs);
1774:   if (auto c = lhs_hi <=> rhs_hi; c != std::strong_ordering::equal) {
1775:     return c;
1776:   }
1777:   const uint32_t lhs_lo = time_internal::GetRepLo(lhs);
1778:   const uint32_t rhs_lo = time_internal::GetRepLo(rhs);
1779:   return (lhs_hi == (std::numeric_limits<int64_t>::min)())
1780:              ? (lhs_lo + 1) <=> (rhs_lo + 1)
1781:              : lhs_lo <=> rhs_lo;
1782: }
1783: 
1784: #endif  // ABSL_INTERNAL_TIME_HAS_THREE_WAY_COMPARISON
1785: 
1786: ABSL_ATTRIBUTE_CONST_FUNCTION constexpr bool operator==(Duration lhs,
1787:                                                         Duration rhs) {
1788:   return time_internal::GetRepHi(lhs) == time_internal::GetRepHi(rhs) &&
1789:          time_internal::GetRepLo(lhs) == time_internal::GetRepLo(rhs);
1790: }
1791: 
1792: ABSL_ATTRIBUTE_CONST_FUNCTION constexpr Duration operator-(Duration d) {
1793:   // This is a little interesting because of the special cases.
1794:   //
1795:   // If rep_lo_ is zero, we have it easy; it's safe to negate rep_hi_, we're
1796:   // dealing with an integral number of seconds, and the only special case is
1797:   // the maximum negative finite duration, which can't be negated.
1798:   //
1799:   // Infinities stay infinite, and just change direction.
1800:   //
1801:   // Finally we're in the case where rep_lo_ is non-zero, and we can borrow
1802:   // a second's worth of ticks and avoid overflow (as negating int64_t-min + 1
1803:   // is safe).
1804:   return time_internal::GetRepLo(d) == 0
1805:              ? time_internal::GetRepHi(d) ==
1806:                        (std::numeric_limits<int64_t>::min)()
1807:                    ? InfiniteDuration()
1808:                    : time_internal::MakeDuration(-time_internal::GetRepHi(d))
1809:              : time_internal::IsInfiniteDuration(d)
1810:                    ? time_internal::OppositeInfinity(d)
1811:                    : time_internal::MakeDuration(
1812:                          time_internal::NegateAndSubtractOne(
1813:                              time_internal::GetRepHi(d)),
1814:                          time_internal::kTicksPerSecond -
1815:                              time_internal::GetRepLo(d));
1816: }
1817: 
1818: ABSL_ATTRIBUTE_CONST_FUNCTION constexpr Duration InfiniteDuration() {
1819:   return time_internal::MakeDuration((std::numeric_limits<int64_t>::max)(),
1820:                                      ~uint32_t{0});
1821: }
1822: 
1823: ABSL_ATTRIBUTE_PURE_FUNCTION constexpr Duration FromChrono(
1824:     const std::chrono::nanoseconds& d) {
1825:   return time_internal::FromChrono(d);
1826: }
1827: ABSL_ATTRIBUTE_PURE_FUNCTION constexpr Duration FromChrono(
1828:     const std::chrono::microseconds& d) {
1829:   return time_internal::FromChrono(d);
1830: }
1831: ABSL_ATTRIBUTE_PURE_FUNCTION constexpr Duration FromChrono(
1832:     const std::chrono::milliseconds& d) {
1833:   return time_internal::FromChrono(d);
1834: }
1835: ABSL_ATTRIBUTE_PURE_FUNCTION constexpr Duration FromChrono(
1836:     const std::chrono::seconds& d) {
1837:   return time_internal::FromChrono(d);
1838: }
1839: ABSL_ATTRIBUTE_PURE_FUNCTION constexpr Duration FromChrono(
