1841:   return time_internal::FromChrono(d);
1842: }
1843: ABSL_ATTRIBUTE_PURE_FUNCTION constexpr Duration FromChrono(
1844:     const std::chrono::hours& d) {
1845:   return time_internal::FromChrono(d);
1846: }
