1848: ABSL_ATTRIBUTE_CONST_FUNCTION constexpr Time FromUnixNanos(int64_t ns) {
1849:   return time_internal::FromUnixDuration(Nanoseconds(ns));
1850: }
1851: 
1852: ABSL_ATTRIBUTE_CONST_FUNCTION constexpr Time FromUnixMicros(int64_t us) {
1853:   return time_internal::FromUnixDuration(Microseconds(us));
1854: }
1855: 
1856: ABSL_ATTRIBUTE_CONST_FUNCTION constexpr Time FromUnixMillis(int64_t ms) {
1857:   return time_internal::FromUnixDuration(Milliseconds(ms));
1858: }
