1868: ABSL_ATTRIBUTE_CONST_FUNCTION constexpr int64_t ToInt64Nanoseconds(Duration d) {
1869:   if (time_internal::GetRepHi(d) >= 0 &&
1870:       time_internal::GetRepHi(d) >> 33 == 0) {
1871:     return (time_internal::GetRepHi(d) * 1000 * 1000 * 1000) +
1872:            (time_internal::GetRepLo(d) / time_internal::kTicksPerNanosecond);
1873:   } else {
1874:     return d / Nanoseconds(1);
1875:   }
1876: }
1877: 
1878: ABSL_ATTRIBUTE_CONST_FUNCTION constexpr int64_t ToInt64Microseconds(
1879:     Duration d) {
1880:   if (time_internal::GetRepHi(d) >= 0 &&
1881:       time_internal::GetRepHi(d) >> 43 == 0) {
1882:     return (time_internal::GetRepHi(d) * 1000 * 1000) +
1883:            (time_internal::GetRepLo(d) /
1884:             (time_internal::kTicksPerNanosecond * 1000));
1885:   } else {
1886:     return d / Microseconds(1);
1887:   }
1888: }
1889: 
1890: ABSL_ATTRIBUTE_CONST_FUNCTION constexpr int64_t ToInt64Milliseconds(
1891:     Duration d) {
1892:   if (time_internal::GetRepHi(d) >= 0 &&
1893:       time_internal::GetRepHi(d) >> 53 == 0) {
1894:     return (time_internal::GetRepHi(d) * 1000) +
1895:            (time_internal::GetRepLo(d) /
1896:             (time_internal::kTicksPerNanosecond * 1000 * 1000));
1897:   } else {
1898:     return d / Milliseconds(1);
1899:   }
1900: }
1901: 
1902: ABSL_ATTRIBUTE_CONST_FUNCTION constexpr int64_t ToInt64Seconds(Duration d) {
1903:   int64_t hi = time_internal::GetRepHi(d);
1904:   if (time_internal::IsInfiniteDuration(d)) return hi;
1905:   if (hi < 0 && time_internal::GetRepLo(d) != 0) ++hi;
1906:   return hi;
1907: }
1908: 
1909: ABSL_ATTRIBUTE_CONST_FUNCTION constexpr int64_t ToInt64Minutes(Duration d) {
1910:   int64_t hi = time_internal::GetRepHi(d);
1911:   if (time_internal::IsInfiniteDuration(d)) return hi;
1912:   if (hi < 0 && time_internal::GetRepLo(d) != 0) ++hi;
1913:   return hi / 60;
1914: }
1915: 
1916: ABSL_ATTRIBUTE_CONST_FUNCTION constexpr int64_t ToInt64Hours(Duration d) {
1917:   int64_t hi = time_internal::GetRepHi(d);
1918:   if (time_internal::IsInfiniteDuration(d)) return hi;
1919:   if (hi < 0 && time_internal::GetRepLo(d) != 0) ++hi;
1920:   return hi / (60 * 60);
1921: }
