11717: std::pair<unsigned, unsigned> WMMAMmaOpGenericAdaptorBase::getODSOperandIndexAndLength(unsigned index, unsigned odsOperandsSize) {
11718:   bool isVariadic[] = {true};
11719:   int prevVariadicCount = 0;
11720:   for (unsigned i = 0; i < index; ++i)
11721:     if (isVariadic[i]) ++prevVariadicCount;
11722: 
11723:   // Calculate how many dynamic values a static variadic operand corresponds to.
11724:   // This assumes all static variadic operands have the same dynamic value count.
11725:   int variadicSize = (odsOperandsSize - 0) / 1;
11726:   // `index` passed in as the parameter is the static index which counts each
11727:   // operand (variadic or not) as size 1. So here for each previous static variadic
11728:   // operand, we need to offset by (variadicSize - 1) to get where the dynamic
11729:   // value pack for this static operand starts.
11730:   int start = index + (variadicSize - 1) * prevVariadicCount;
11731:   int size = isVariadic[index] ? variadicSize : 1;
11732:   return {start, size};
11733: }
