12568: std::pair<unsigned, unsigned> WMMAStoreOpGenericAdaptorBase::getODSOperandIndexAndLength(unsigned index, unsigned odsOperandsSize) {
12569:   bool isVariadic[] = {false, true, false};
12570:   int prevVariadicCount = 0;
12571:   for (unsigned i = 0; i < index; ++i)
12572:     if (isVariadic[i]) ++prevVariadicCount;
12573: 
12574:   // Calculate how many dynamic values a static variadic operand corresponds to.
12575:   // This assumes all static variadic operands have the same dynamic value count.
12576:   int variadicSize = (odsOperandsSize - 2) / 1;
12577:   // `index` passed in as the parameter is the static index which counts each
12578:   // operand (variadic or not) as size 1. So here for each previous static variadic
12579:   // operand, we need to offset by (variadicSize - 1) to get where the dynamic
12580:   // value pack for this static operand starts.
12581:   int start = index + (variadicSize - 1) * prevVariadicCount;
12582:   int size = isVariadic[index] ? variadicSize : 1;
12583:   return {start, size};
12584: }
