12672: std::pair<unsigned, unsigned> WMMAStoreOp::getODSOperandIndexAndLength(unsigned index) {
12673:   bool isVariadic[] = {false, true, false};
12674:   int prevVariadicCount = 0;
12675:   for (unsigned i = 0; i < index; ++i)
12676:     if (isVariadic[i]) ++prevVariadicCount;
12677: 
12678:   // Calculate how many dynamic values a static variadic operand corresponds to.
12679:   // This assumes all static variadic operands have the same dynamic value count.
12680:   int variadicSize = (getOperation()->getNumOperands() - 2) / 1;
12681:   // `index` passed in as the parameter is the static index which counts each
12682:   // operand (variadic or not) as size 1. So here for each previous static variadic
12683:   // operand, we need to offset by (variadicSize - 1) to get where the dynamic
12684:   // value pack for this static operand starts.
12685:   int start = index + (variadicSize - 1) * prevVariadicCount;
12686:   int size = isVariadic[index] ? variadicSize : 1;
12687:   return {start, size};
12688: }
