79: //===----------------------------------------------------------------------===//
80: //
81: //  Reader class.
82: //
83: //===----------------------------------------------------------------------===//
84: 
85: /// This class abstracts over the information stored in file headers,
86: /// as well as providing the buffers and methods for parsing those headers.
87: class SparseTensorReader final {
88: public:
89:   enum class ValueKind : uint8_t {
90:     // The value before calling `readHeader`.
91:     kInvalid = 0,
92:     // Values that can be set by `readMMEHeader`.
93:     kPattern = 1,
94:     kReal = 2,
95:     kInteger = 3,
96:     kComplex = 4,
97:     // The value set by `readExtFROSTTHeader`.
98:     kUndefined = 5
99:   };
100: 
101:   explicit SparseTensorReader(const char *filename) : filename(filename) {
102:     assert(filename && "Received nullptr for filename");
103:   }
104: 
105:   // Disallows copying, to avoid duplicating the `file` pointer.
106:   SparseTensorReader(const SparseTensorReader &) = delete;
107:   SparseTensorReader &operator=(const SparseTensorReader &) = delete;
108: 
109:   /// Factory method to allocate a new reader, open the file, read the
110:   /// header, and validate that the actual contents of the file match
111:   /// the expected `dimShape` and `valTp`.
112:   static SparseTensorReader *create(const char *filename, uint64_t dimRank,
113:                                     const uint64_t *dimShape,
114:                                     PrimaryType valTp) {
115:     SparseTensorReader *reader = new SparseTensorReader(filename);
116:     reader->openFile();
117:     reader->readHeader();
118:     if (!reader->canReadAs(valTp))
119:       MLIR_SPARSETENSOR_FATAL(
120:           "Tensor element type %d not compatible with values in file %s\n",
121:           static_cast<int>(valTp), filename);
122:     reader->assertMatchesShape(dimRank, dimShape);
123:     return reader;
124:   }
125: 
126:   // This dtor tries to avoid leaking the `file`.  (Though it's better
127:   // to call `closeFile` explicitly when possible, since there are
128:   // circumstances where dtors are not called reliably.)
129:   ~SparseTensorReader() { closeFile(); }
130: 
131:   /// Opens the file for reading.
132:   void openFile();
133: 
134:   /// Closes the file.
135:   void closeFile();
136: 
137:   /// Reads and parses the file's header.
138:   void readHeader();
139: 
140:   /// Returns the stored value kind.
141:   ValueKind getValueKind() const { return valueKind_; }
142: 
143:   /// Checks if a header has been successfully read.
144:   bool isValid() const { return valueKind_ != ValueKind::kInvalid; }
145: 
146:   /// Checks if the file's ValueKind can be converted into the given
147:   /// tensor PrimaryType.  Is only valid after parsing the header.
148:   bool canReadAs(PrimaryType valTy) const;
149: 
150:   /// Gets the MME "pattern" property setting.  Is only valid after
151:   /// parsing the header.
152:   bool isPattern() const {
153:     assert(isValid() && "Attempt to isPattern() before readHeader()");
154:     return valueKind_ == ValueKind::kPattern;
155:   }
156: 
157:   /// Gets the MME "symmetric" property setting.  Is only valid after
158:   /// parsing the header.
159:   bool isSymmetric() const {
160:     assert(isValid() && "Attempt to isSymmetric() before readHeader()");
161:     return isSymmetric_;
162:   }
163: 
164:   /// Gets the dimension-rank of the tensor.  Is only valid after parsing
165:   /// the header.
166:   uint64_t getRank() const {
167:     assert(isValid() && "Attempt to getRank() before readHeader()");
168:     return idata[0];
169:   }
170: 
171:   /// Gets the number of stored elements.  Is only valid after parsing
172:   /// the header.
173:   uint64_t getNSE() const {
174:     assert(isValid() && "Attempt to getNSE() before readHeader()");
175:     return idata[1];
176:   }
177: 
178:   /// Gets the dimension-sizes array.  The pointer itself is always
179:   /// valid; however, the values stored therein are only valid after
180:   /// parsing the header.
181:   const uint64_t *getDimSizes() const { return idata + 2; }
182: 
183:   /// Safely gets the size of the given dimension.  Is only valid
184:   /// after parsing the header.
185:   uint64_t getDimSize(uint64_t d) const {
186:     assert(d < getRank() && "Dimension out of bounds");
187:     return idata[2 + d];
188:   }
189: 
190:   /// Asserts the shape subsumes the actual dimension sizes.  Is only
191:   /// valid after parsing the header.
192:   void assertMatchesShape(uint64_t rank, const uint64_t *shape) const;
193: 
194:   /// Allocates a new sparse-tensor storage object with the given encoding,
195:   /// initializes it by reading all the elements from the file, and then
196:   /// closes the file. Templated on P, I, and V.
197:   template <typename P, typename I, typename V>
198:   SparseTensorStorage<P, I, V> *
199:   readSparseTensor(uint64_t lvlRank, const uint64_t *lvlSizes,
200:                    const DimLevelType *lvlTypes, const uint64_t *dim2lvl,
201:                    const uint64_t *lvl2dim) {
202:     const uint64_t dimRank = getRank();
203:     MapRef map(dimRank, lvlRank, dim2lvl, lvl2dim);
204:     auto *coo = readCOO<V>(map, lvlSizes);
205:     auto *tensor = SparseTensorStorage<P, I, V>::newFromCOO(
206:         dimRank, getDimSizes(), lvlRank, lvlTypes, lvl2dim, *coo);
207:     delete coo;
208:     return tensor;
209:   }
210: 
211:   /// Reads the COO tensor from the file, stores the coordinates and values to
212:   /// the given buffers, returns a boolean value to indicate whether the COO
213:   /// elements are sorted.
214:   template <typename C, typename V>
215:   bool readToBuffers(uint64_t lvlRank, const uint64_t *dim2lvl,
216:                      const uint64_t *lvl2dim, C *lvlCoordinates, V *values);
217: 
218: private:
219:   /// Attempts to read a line from the file.
220:   void readLine();
221: 
222:   /// Reads the next line of the input file and parses the coordinates
223:   /// into the `dimCoords` argument.  Returns the position in the `line`
224:   /// buffer where the element's value should be parsed from.
225:   template <typename C>
226:   char *readCoords(C *dimCoords) {
227:     readLine();
228:     // Local variable for tracking the parser's position in the `line` buffer.
229:     char *linePtr = line;
230:     for (uint64_t dimRank = getRank(), d = 0; d < dimRank; ++d) {
231:       // Parse the 1-based coordinate.
232:       uint64_t c = strtoul(linePtr, &linePtr, 10);
233:       // Store the 0-based coordinate.
234:       dimCoords[d] = static_cast<C>(c - 1);
235:     }
236:     return linePtr;
237:   }
238: 
239:   /// Reads all the elements from the file while applying the given map.
240:   template <typename V>
241:   SparseTensorCOO<V> *readCOO(const MapRef &map, const uint64_t *lvlSizes);
242: 
243:   /// The implementation of `readCOO` that is templated `IsPattern` in order
244:   /// to perform LICM without needing to duplicate the source code.
245:   template <typename V, bool IsPattern>
246:   void readCOOLoop(const MapRef &map, SparseTensorCOO<V> *coo);
247: 
248:   /// The internal implementation of `readToBuffers`. We template over
249:   /// `IsPattern` in order to perform LICM without needing to duplicate
250:   /// the source code.
251:   template <typename C, typename V, bool IsPattern>
252:   bool readToBuffersLoop(const MapRef &map, C *lvlCoordinates, V *values);
253: 
254:   /// Reads the MME header of a general sparse matrix of type real.
255:   void readMMEHeader();
256: 
257:   /// Reads the "extended" FROSTT header. Although not part of the
258:   /// documented format, we assume that the file starts with optional
259:   /// comments followed by two lines that define the rank, the number of
260:   /// nonzeros, and the dimensions sizes (one per rank) of the sparse tensor.
261:   void readExtFROSTTHeader();
262: 
263:   static constexpr int kColWidth = 1025;
264:   const char *const filename;
265:   FILE *file = nullptr;
266:   ValueKind valueKind_ = ValueKind::kInvalid;
267:   bool isSymmetric_ = false;
268:   uint64_t idata[512];
269:   char line[kColWidth];
270: };
271: 
272: //===----------------------------------------------------------------------===//
273: //
274: //  Reader class methods.
275: //
276: //===----------------------------------------------------------------------===//
277: 
278: template <typename V>
279: SparseTensorCOO<V> *SparseTensorReader::readCOO(const MapRef &map,
280:                                                 const uint64_t *lvlSizes) {
281:   assert(isValid() && "Attempt to readCOO() before readHeader()");
282:   // Prepare a COO object with the number of stored elems as initial capacity.
283:   auto *coo = new SparseTensorCOO<V>(map.getLvlRank(), lvlSizes, getNSE());
284:   // Enter the reading loop.
285:   if (isPattern())
286:     readCOOLoop<V, true>(map, coo);
287:   else
288:     readCOOLoop<V, false>(map, coo);
289:   // Close the file and return the COO.
290:   closeFile();
291:   return coo;
292: }
293: 
294: template <typename V, bool IsPattern>
295: void SparseTensorReader::readCOOLoop(const MapRef &map,
296:                                      SparseTensorCOO<V> *coo) {
297:   const uint64_t dimRank = map.getDimRank();
298:   const uint64_t lvlRank = map.getLvlRank();
299:   assert(dimRank == getRank());
300:   std::vector<uint64_t> dimCoords(dimRank);
301:   std::vector<uint64_t> lvlCoords(lvlRank);
302:   for (uint64_t k = 0, nse = getNSE(); k < nse; k++) {
303:     char *linePtr = readCoords(dimCoords.data());
304:     const V value = detail::readValue<V, IsPattern>(&linePtr);
305:     map.pushforward(dimCoords.data(), lvlCoords.data());
306:     coo->add(lvlCoords, value);
307:   }
308: }
309: 
310: template <typename C, typename V>
311: bool SparseTensorReader::readToBuffers(uint64_t lvlRank,
312:                                        const uint64_t *dim2lvl,
313:                                        const uint64_t *lvl2dim,
314:                                        C *lvlCoordinates, V *values) {
315:   assert(isValid() && "Attempt to readCOO() before readHeader()");
316:   MapRef map(getRank(), lvlRank, dim2lvl, lvl2dim);
317:   bool isSorted =
318:       isPattern() ? readToBuffersLoop<C, V, true>(map, lvlCoordinates, values)
319:                   : readToBuffersLoop<C, V, false>(map, lvlCoordinates, values);
320:   closeFile();
321:   return isSorted;
322: }
323: 
324: template <typename C, typename V, bool IsPattern>
325: bool SparseTensorReader::readToBuffersLoop(const MapRef &map, C *lvlCoordinates,
326:                                            V *values) {
327:   const uint64_t dimRank = map.getDimRank();
328:   const uint64_t lvlRank = map.getLvlRank();
329:   const uint64_t nse = getNSE();
330:   assert(dimRank == getRank());
331:   std::vector<C> dimCoords(dimRank);
332:   bool isSorted = false;
333:   char *linePtr;
334:   const auto readNextElement = [&]() {
335:     linePtr = readCoords<C>(dimCoords.data());
336:     map.pushforward(dimCoords.data(), lvlCoordinates);
337:     *values = detail::readValue<V, IsPattern>(&linePtr);
338:     if (isSorted) {
339:       // Note that isSorted is set to false when reading the first element,
340:       // to guarantee the safeness of using prevLvlCoords.
341:       C *prevLvlCoords = lvlCoordinates - lvlRank;
342:       for (uint64_t l = 0; l < lvlRank; ++l) {
343:         if (prevLvlCoords[l] != lvlCoordinates[l]) {
344:           if (prevLvlCoords[l] > lvlCoordinates[l])
345:             isSorted = false;
346:           break;
347:         }
348:       }
349:     }
350:     lvlCoordinates += lvlRank;
351:     ++values;
352:   };
353:   readNextElement();
354:   isSorted = true;
355:   for (uint64_t n = 1; n < nse; ++n)
356:     readNextElement();
357:   return isSorted;
358: }
359: 
360: /// Writes the sparse tensor to `filename` in extended FROSTT format.
361: template <typename V>
362: inline void writeExtFROSTT(const SparseTensorCOO<V> &coo,
363:                            const char *filename) {
364:   assert(filename && "Got nullptr for filename");
365:   const auto &dimSizes = coo.getDimSizes();
366:   const auto &elements = coo.getElements();
367:   const uint64_t dimRank = coo.getRank();
368:   const uint64_t nse = elements.size();
369:   std::fstream file;
370:   file.open(filename, std::ios_base::out | std::ios_base::trunc);
371:   assert(file.is_open());
372:   file << "; extended FROSTT format\n" << dimRank << " " << nse << std::endl;
373:   for (uint64_t d = 0; d < dimRank - 1; ++d)
374:     file << dimSizes[d] << " ";
375:   file << dimSizes[dimRank - 1] << std::endl;
376:   for (uint64_t i = 0; i < nse; ++i) {
377:     const auto &coords = elements[i].coords;
378:     for (uint64_t d = 0; d < dimRank; ++d)
379:       file << (coords[d] + 1) << " ";
380:     file << elements[i].value << std::endl;
381:   }
382:   file.flush();
383:   file.close();
384:   assert(file.good());
385: }
