36: class ITensor
37: {
38: public:
39:   virtual ~ITensor();
40: 
41: public:
42:   virtual uint8_t *buffer() const = 0;
43:   virtual size_t total_size() const = 0;
44:   virtual size_t calcOffset(const ir::Coordinates &coords) const = 0;
45:   virtual ir::Layout layout() const = 0;
46:   virtual ir::DataType data_type() const = 0;
47:   virtual float data_scale() const = 0;
48:   virtual int32_t data_zero_point() const = 0;
49:   virtual const std::vector<float> &data_scales() const = 0;
50:   virtual const std::vector<int32_t> &data_zero_points() const = 0;
51:   virtual bool has_padding() const = 0;
52:   virtual void access(const std::function<void(ITensor &tensor)> &fn) = 0;
53: 
54:   /**
55:    * @brief Set the shape to @c shape and possibly re-allocate the buffer
56:    *
57:    * If a tensor is dynamic tensor and previously allocated memory exists,
58:    * it will be deallocated.
59:    * If a tensor is static tensor (with previously allocated memory by StaticTensorManager),
60:    * @c buffer() will be overwriten
61:    *
62:    * @param shape tensor's new shape. While allocating memory for this new_shape,
63:    *              tensor's shape is set to new_shape
64:    * @return true If applying shape is successful
65:    * @return false If not applying shape is not supported (it throws for other errors)
66:    */
67:   virtual bool applyShape(const ir::Shape &) { return false; }
68: 
69:   /**
70:    * @brief Return true if the tensor is constant
71:    */
72:   virtual bool is_constant() const
73:   {
74:     throw std::runtime_error("This backend does not support checking constant");
75:   }
76: 
77:   /**
78:    * @brief Return true if the tensor needs dynamic allocation, meaning that during compile-time
79:    *        the outpus shape cannot be known and the output shape is calculated during
80:    *        kernel execution-time.
81:    */
82:   virtual bool is_dynamic() const = 0;
83: 
84:   /// @brief set this tensor dynamic
85:   virtual void set_dynamic()
86:   {
87:     throw std::runtime_error("This backend does not support dynamic tensor");
88:   }
89: 
90:   /// @brief Dealloc the buffer (only for dynamic tensors)
91:   virtual void deallocBuffer()
92:   {
93:     throw std::runtime_error("This backend does not support resetting buffer");
94:   }
95: 
96:   /**
97:    * @brief Set the shape of tenser to new_shape
98:    * @note  Higer dimension will be placed on front.
99:    */
100:   virtual void setShape(const ir::Shape &new_shape)
101:   {
102:     UNUSED_RELEASE(new_shape);
103:     throw std::runtime_error("This backend does not support dynamic setShape");
104:   }
105: 
106:   /**
107:    * @brief Get ir::Shape of tensor
108:    * @note  Higer dimension will be placed on front.
109:    */
110:   virtual ir::Shape getShape() const = 0;
111: 
112:   virtual bool is_subtensor() const { return false; }
113:   virtual bool needMemoryMap() const { return false; }
114:   virtual void enqueueWriteBuffer(const void *, bool)
115:   {
116:     throw std::runtime_error("This backend does not support enqueueWriteBuffer");
117:   }
118:   virtual void enqueueReadBuffer(void *, bool)
119:   {
120:     throw std::runtime_error("This backend does not support enqueueReadBuffer");
121:   }
122: };
